// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.base.SailSink;
import org.eclipse.rdf4j.sail.lmdb.LmdbOperatorFeedbackStats.MutationExtent;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The proportional mutation decay of learned evidence (review finding 3.7.5 (a)) is only as good as the commit extent
 * the LMDB sink reports. The numerator must be the number of statements the transaction actually changed - never the
 * frontier mutation-journal delta, which advances once per transaction when the frontier estimator is off - and the
 * denominator the size of the committed store. The extent and the touched predicates of a commit must also survive a
 * join-estimator failure inside the transaction: the data still commits, so the learned evidence must still decay for
 * all of it.
 * <p>
 * The commits are observed through {@link LmdbOperatorFeedbackStats#setLearnedStateObserver}, never through a Mockito
 * spy: spying the final stats class retransforms it for the whole test JVM, after which every later runtime feedback
 * publication allocates (LmdbRuntimeFeedbackTargetTest asserts that publication allocates nothing).
 */
class LmdbCommitMutationExtentTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P1 = VF.createIRI("urn:test:commit-extent:p1");
	private static final IRI P2 = VF.createIRI("urn:test:commit-extent:p2");

	@Test
	void commitReportsMutatedStatementsAndTheCommittedStoreSize(@TempDir Path dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), config(FrontierEstimatorMode.AUTHORITATIVE));
		store.init();
		try {
			RecordedMutations mutations = recordStoreMutations(store);

			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				for (int i = 0; i < 3; i++) {
					connection.addStatement(VF.createIRI("urn:test:commit-extent:s" + i), P1, VF.createLiteral(i));
				}
				connection.commit();
			}
			assertEquals(new MutationExtent(3L, 3L), lastExtent(mutations), "three added statements, three committed");

			mutations.clear();
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.removeStatements(VF.createIRI("urn:test:commit-extent:s0"), P1, null);
				connection.commit();
			}
			assertEquals(new MutationExtent(1L, 2L), lastExtent(mutations), "one removed statement, two left");

			mutations.clear();
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(VF.createIRI("urn:test:commit-extent:s9"), P2, VF.createLiteral(9));
				connection.commit();
			}
			assertEquals(new MutationExtent(1L, 3L), lastExtent(mutations),
					"the extent of one commit must not accumulate the statements of earlier commits");
		} finally {
			store.shutDown();
		}
	}

	@Test
	void largeTransactionWithTheFrontierEstimatorOffCountsEveryStatement(@TempDir Path dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), config(FrontierEstimatorMode.OFF));
		store.init();
		try {
			RecordedMutations mutations = recordStoreMutations(store);
			int statements = 2_000;

			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				for (int i = 0; i < statements; i++) {
					connection.addStatement(VF.createIRI("urn:test:commit-extent:bulk:" + i), P1,
							VF.createLiteral(i));
				}
				connection.commit();
			}

			assertEquals(new MutationExtent(statements, statements), lastExtent(mutations),
					"a bulk load is a full rewrite however the frontier journal numbers it");
		} finally {
			store.shutDown();
		}
	}

	@Test
	void joinEstimatorFailureInsideTheTransactionMustNotShrinkTheCommitExtent(@TempDir Path dataDir)
			throws Exception {
		LmdbStoreConfig config = config(FrontierEstimatorMode.AUTHORITATIVE).setBulkOperationSize(0);
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		store.init();
		try {
			RecordedMutations mutations = recordStoreMutations(store);
			LmdbSailStore backingStore = store.getBackingStore();

			SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE);
			try {
				sink.approve(VF.createIRI("urn:test:commit-extent:before"), P1, VF.createLiteral("before"), null);
				// the join estimator gives up on its in-transaction state; the statements still commit
				Method recover = sink.getClass()
						.getDeclaredMethod("recoverEstimatorAfterFailure", String.class, RuntimeException.class);
				recover.setAccessible(true);
				recover.invoke(sink, "applying add", new IllegalStateException("injected estimator failure"));
				sink.approve(VF.createIRI("urn:test:commit-extent:after"), P2, VF.createLiteral("after"), null);
				sink.flush();
			} finally {
				sink.close();
			}

			RecordedMutation mutation = mutations.last();
			assertEquals(new MutationExtent(2L, 2L), mutation.extent(),
					"both committed statements count, including the one written before the estimator failure");
			assertEquals(2, mutation.predicateIds().size(),
					"the predicate written before the estimator failure must still have its evidence decayed");
		} finally {
			store.shutDown();
		}
	}

	private static LmdbStoreConfig config(FrontierEstimatorMode mode) {
		return new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(mode)
				.setFrontierSynopsisBudgetBytes(1024L * 1024L);
	}

	private static RecordedMutations recordStoreMutations(LmdbStore store) throws Exception {
		LmdbSailStore backingStore = store.getBackingStore();
		Field field = LmdbSailStore.class.getDeclaredField("operatorFeedbackStats");
		field.setAccessible(true);
		LmdbOperatorFeedbackStats stats = (LmdbOperatorFeedbackStats) field.get(backingStore);
		assertNotNull(stats, "precondition: learned services are enabled for this store");
		RecordedMutations recorded = new RecordedMutations();
		stats.setLearnedStateObserver(recorded);
		return recorded;
	}

	private static MutationExtent lastExtent(RecordedMutations mutations) {
		return mutations.last().extent();
	}

	private record RecordedMutation(long committedStatementMutationStamp, Set<Long> predicateIds,
			MutationExtent extent) {
	}

	private static final class RecordedMutations implements LmdbOperatorFeedbackStats.LearnedStateObserver {

		private final List<RecordedMutation> mutations = new ArrayList<>();

		@Override
		public synchronized void storeMutationRecorded(long committedStatementMutationStamp, Set<Long> predicateIds,
				MutationExtent extent) {
			mutations.add(new RecordedMutation(committedStatementMutationStamp,
					predicateIds == null ? Set.of() : Set.copyOf(predicateIds), extent));
		}

		synchronized void clear() {
			mutations.clear();
		}

		synchronized RecordedMutation last() {
			assertFalse(mutations.isEmpty(), "the commit must reach the learned evidence as a store mutation");
			return mutations.get(mutations.size() - 1);
		}
	}
}
